// Clean-room exhaustive solver for bounded weighted popular matchings.
const N:usize=4;const F:usize=6;
fn decode(code0:usize,n:usize,m:usize,a:*[N]i64)bool{var code=code0;var used:u32=0;for(0..n)|i|{const digit=code%(m+1);code/=(m+1);a[i]=@as(i64,@intCast(digit))-1;if(digit>0){const bit:u32=@as(u32,1)<<@intCast(digit-1);if(used&bit!=0)return false;used|=bit;}}return true;}
fn lexless(a:[N]i64,b:[N]i64,n:usize)bool{for(0..n)|i|{if(a[i]!=b[i])return a[i]<b[i];}return false;}
fn put(out:[*]u8,at:usize,x:i64)void{const bits:u64=@bitCast(x);for(0..8)|i|out[at+i]=@truncate(bits>>@intCast(8*i));}
export fn weighted_popular_matching(v:[*c]const i64,length:usize,out_opt:?[*]u8,capacity:usize)i64{if(v==null||length<4||length>22||v[0]<1||v[0]>4||v[1]<1||v[1]>4)return -1;const n:usize=@intCast(v[0]);const m:usize=@intCast(v[1]);if(length!=2+n+n*m)return -1;for(0..n)|i|{const weight=v[2+i];if(weight<1 or weight>1000)return -1;var seen:u32=0;for(0..m)|j|{const rank=v[2+n+i*m+j];if(rank<0 or rank>=@as(i64,@intCast(m)))return -1;const bit:u32=@as(u32,1)<<@intCast(rank);if(seen&bit!=0)return -1;seen|=bit;}}
 var total:usize=1;for(0..n)|_|total*=m+1;var best_card:i64=-1;var best:[N]i64=@splat(-1);for(0..total)|code|{var cand:[N]i64=@splat(-1);if(!decode(code,n,m,&cand))continue;var popular=true;for(0..total)|other_code|{if(!popular)break;var other:[N]i64=@splat(-1);if(!decode(other_code,n,m,&other))continue;var score:i64=0;for(0..n)|i|{const rc=if(cand[i]<0)@as(i64,@intCast(m)) else v[2+n+i*m+@as(usize,@intCast(cand[i]))];const ro=if(other[i]<0)@as(i64,@intCast(m)) else v[2+n+i*m+@as(usize,@intCast(other[i]))];if(ro<rc)score+=v[2+i] else if(ro>rc)score-=v[2+i];}if(score>0)popular=false;}if(popular){var card:i64=0;for(0..n)|i|if(cand[i]>=0){card+=1;};if(card>best_card or (card==best_card and lexless(cand,best,n))){best_card=card;best=cand;}}}
 var fields:[F]i64=@splat(0);fields[0]=if(best_card<0)0 else 1;fields[1]=if(best_card<0)0 else best_card;for(0..n)|i|fields[2+i]=if(best_card<0)-1 else best[i];const bytes=8*(n+2);if(out_opt==null or capacity<bytes)return -2;const out=out_opt.?;var staged:[F*8]u8=@splat(0);for(0..n+2)|i|put(&staged,8*i,fields[i]);@memcpy(out[0..bytes],staged[0..bytes]);return @intCast(bytes);}
